1	import "server-only";
2	
3	/**
4	 * Discord OAuth2 (Authorization Code grant, `identify` scope only) for the
5	 * staff Discord-account-linking flow — see
6	 * app/api/admin/discord/authorize/route.ts and
7	 * app/api/admin/discord/callback/route.ts.
8	 *
9	 * This is a SEPARATE credential from the bot token used everywhere else in
10	 * lib/discord.ts: the bot token authenticates the platform's own bot user for
11	 * REST calls (create channel, post message, …); this client id/secret pair
12	 * authenticates the Nxeon Discord APPLICATION to run a normal user-consent
13	 * OAuth flow so a staff member can prove "this Discord account is mine".
14	 * Same Discord application, two different credential types — see Discord's
15	 * own developer portal, which lists both under one app.
16	 *
17	 * Nxeon is a confidential (server-side) client, so this is the plain
18	 * Authorization Code flow with a client secret — no PKCE needed (PKCE exists
19	 * for clients that CAN'T keep a secret; we can). Discord's token endpoint
20	 * accepts client_secret_post (credentials in the form body), which is what's
21	 * used below.
22	 *
23	 * ── STATE / CSRF ─────────────────────────────────────────────────────────
24	 * Rather than stash `state` server-side (a cookie, a DB row) the way
25	 * lib/cloudflare-oauth.ts's flow does, `state` here IS a short-lived signed
26	 * JWT (via `jose`, the same library and secret — AUTH_SECRET — lib/auth.ts's
27	 * session cookie uses) embedding the initiating staff user's id and a
28	 * distinguishing `typ` claim. Discord round-trips `state` verbatim, so:
29	 *   - Signature + expiry verification is real CSRF protection: an attacker
30	 *     cannot forge or replay an old value without AUTH_SECRET.
31	 *   - No server-side storage is needed at all (no cookie to lose across a
32	 *     redirect, no DB row to clean up).
33	 *   - It's a pure, deterministic function — easy to unit test without a
34	 *     cookie jar or DB (see test/discord-oauth-state.test.ts).
35	 * CRITICAL: `state` is CSRF protection ONLY. The callback route re-derives
36	 * the actual signed-in user from the real session (`requireArea("support")`)
37	 * and only uses the state's embedded uid to CONFIRM it matches — never as the
38	 * source of truth for whose account gets linked. See the callback route's
39	 * top-of-file comment.
40	 */
41	
42	import { SignJWT, jwtVerify } from "jose";
43	import { discordApplicationId, discordClientSecret } from "./discord";
44	
45	const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
46	
47	/** Distinguishes this JWT from a session/impersonation token signed with the same secret. */
48	const STATE_TYP = "discord_oauth_state";
49	/** The unauthenticated "Sign in / Sign up with Discord" variant — no uid to bind, pure CSRF nonce. */
50	export const AUTH_STATE_TYP = "discord_auth_state";
51	
52	/** How long a "Connect Discord" attempt has to complete consent. */
53	const STATE_TTL = "10m";
54	
55	const DISCORD_OAUTH_AUTHORIZE_URL = "https://discord.com/oauth2/authorize";
56	const DISCORD_OAUTH_TOKEN_URL = "https://discord.com/api/v10/oauth2/token";
57	const DISCORD_API_USERS_ME = "https://discord.com/api/v10/users/@me";
58	
59	// NOT appUrl()/APP_URL — same reason as the Google Search Console admin OAuth
60	// integration (app/api/admin/integrations/google-search-console/callback/route.ts):
61	// this codebase's session cookie has no explicit Domain attribute (lib/auth.ts),
62	// so it's host-only — a staff member's session on the admin subdomain and any
63	// session on the bare public domain are two completely separate cookie jars.
64	// Found live: an admin who authorized from the admin subdomain landed back on
65	// this callback via the PUBLIC domain, had no staff session there, and got
66	// silently redirected to /dashboard by requireArea("support") with no
67	// indication anything went wrong. Building this off NXEON_ADMIN_ORIGIN instead
68	// keeps the whole flow on the one host staff sessions actually live on.
69	const ADMIN_ORIGIN = () => (process.env.NXEON_ADMIN_ORIGIN ?? "https://nxeon.cloud").replace(/\/$/, "");
70	
71	/** Must exactly match the redirect URI registered on the Discord application. */
72	export function discordOauthRedirectUri(): string {
73	  return `${ADMIN_ORIGIN()}/api/admin/discord/callback`;
74	}
75	
76	// The main app origin — where the CUSTOMER-facing linking flow's callback
77	// lives (app/api/discord/callback/route.ts), as opposed to the admin-only
78	// one above. A customer's session cookie is bound to the public app origin,
79	// same reasoning as ADMIN_ORIGIN's own comment: keep the flow on the host
80	// the session actually lives on.
81	const PUBLIC_APP_ORIGIN = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
82	
83	/** Must exactly match a SECOND redirect URI registered on the Discord application (customer-facing). */
84	export function discordCustomerOauthRedirectUri(): string {
85	  return `${PUBLIC_APP_ORIGIN()}/api/discord/callback`;
86	}
87	
88	// ---------------------------------------------------------------------------
89	// State (CSRF) — sign / verify
90	// ---------------------------------------------------------------------------
91	
92	/** Mint a fresh `state` value bound to the staff user starting the flow. */
93	export async function signDiscordOauthState(uid: string): Promise<string> {
94	  return new SignJWT({ typ: STATE_TYP })
95	    .setProtectedHeader({ alg: "HS256" })
96	    .setSubject(uid)
97	    .setIssuedAt()
98	    .setExpirationTime(STATE_TTL)
99	    .sign(secret);
100	}
101	
102	/** Mint a state value for the UNAUTHENTICATED "Sign in / Sign up with Discord"
103	 *  flow — no uid to bind (there's no session yet), so this is a pure CSRF
104	 *  nonce distinguished from the linking flow's state purely by `typ`.
105	 *  `next` (already validated by the caller via lib/safe-next.ts) rides along
106	 *  so a visitor who clicked a deep link lands there after signing in, same
107	 *  as the Google flow's `next` query param. */
108	export async function signDiscordAuthState(next?: string | null): Promise<string> {
109	  return new SignJWT({ typ: AUTH_STATE_TYP, ...(next ? { next } : {}) })
110	    .setProtectedHeader({ alg: "HS256" })
111	    .setIssuedAt()
112	    .setExpirationTime(STATE_TTL)
113	    .sign(secret);
114	}
115	
116	export type StateCheck = { ok: true } | { ok: false; error: string };
117	
118	/**
119	 * Verify a `state` value round-tripped from Discord. Checks signature,
120	 * expiry, the `typ` claim (so a session/impersonation cookie value can never
121	 * be replayed here even though it shares a secret), AND that the embedded
122	 * uid matches the user CURRENTLY signed in at callback time — binding the
123	 * flow to one continuous session, not just "signed by us at some point".
124	 *
125	 * Never throws — every failure mode (missing, malformed, expired, wrong
126	 * signature, wrong user) returns `{ ok: false, error }` with a message safe
127	 * to show the staff member.
128	 */
129	export async function verifyDiscordOauthState(state: string | null | undefined, expectedUid: string): Promise<StateCheck> {
130	  if (!state) return { ok: false, error: "Missing state — please start the connection again." };
131	  try {
132	    const { payload } = await jwtVerify(state, secret);
133	    if (payload.typ !== STATE_TYP) {
134	      return { ok: false, error: "Invalid state — please start the connection again." };
135	    }
136	    if (payload.sub !== expectedUid) {
137	      return {
138	        ok: false,
139	        error: "This Discord sign-in was started by a different account. Please try again.",
140	      };
141	    }
142	    return { ok: true };
143	  } catch {
144	    // jose throws for a bad signature, malformed token, AND an expired token
145	    // (JWTExpired) — all three collapse to the same user-facing message.
146	    return { ok: false, error: "That Discord sign-in link expired or was tampered with. Please try again." };
147	  }
148	}
149	
150	/** Verify a state's signature + expiry ONLY, and report which flow minted
151	 *  it (`typ`) plus its bound uid if any — the single callback route uses
152	 *  this to decide whether to run the LINK branch (existing session,
153	 *  matched against `sub` via verifyDiscordOauthState above) or the
154	 *  unauthenticated AUTH/signup branch, without needing two callback routes
155	 *  or a second registered redirect URI. Never throws. */
156	export async function peekDiscordState(
157	  state: string | null | undefined,
158	): Promise<{ ok: true; typ: string; sub?: string; next?: string } | { ok: false }> {
159	  if (!state) return { ok: false };
160	  try {
161	    const { payload } = await jwtVerify(state, secret);
162	    if (typeof payload.typ !== "string") return { ok: false };
163	    return {
164	      ok: true,
165	      typ: payload.typ,
166	      sub: typeof payload.sub === "string" ? payload.sub : undefined,
167	      next: typeof payload.next === "string" ? payload.next : undefined,
168	    };
169	  } catch {
170	    return { ok: false };
171	  }
172	}
173	
174	// ---------------------------------------------------------------------------
175	// Authorization request
176	// ---------------------------------------------------------------------------
177	
178	export async function discordOauthConfigured(): Promise<boolean> {
179	  const [appId, secret] = await Promise.all([discordApplicationId(), discordClientSecret()]);
180	  return Boolean(appId && secret);
181	}
182	
183	/** Build the Discord consent URL for this connection attempt.
184	 *  `redirectUri` defaults to the staff/admin callback for backward compat — pass `discordCustomerOauthRedirectUri()` for the customer-facing flow.
185	 *  `scope` defaults to `identify` (linking only) — the "Sign in / Sign up with Discord" flow passes `identify email guilds.join` (email to
186	 *  match/create a Nxeon account, guilds.join to auto-add them to the server). */
187	export async function discordAuthorizeUrl(
188	  state: string,
189	  redirectUri: string = discordOauthRedirectUri(),
190	  scope: string = "identify",
191	): Promise<string> {
192	  const clientId = await discordApplicationId();
193	  const url = new URL(DISCORD_OAUTH_AUTHORIZE_URL);
194	  url.searchParams.set("client_id", clientId);
195	  url.searchParams.set("redirect_uri", redirectUri);
196	  url.searchParams.set("response_type", "code");
197	  url.searchParams.set("scope", scope);
198	  url.searchParams.set("state", state);
199	  // Force account chooser every time rather than silently reusing a stale
200	  // Discord session — this is an identity proof, not a "keep me logged in".
201	  url.searchParams.set("prompt", "consent");
202	  return url.toString();
203	}
204	
205	// ---------------------------------------------------------------------------
206	// Token endpoint
207	// ---------------------------------------------------------------------------
208	
209	type TokenResponse = {
210	  access_token?: string;
211	  token_type?: string;
212	  scope?: string;
213	  error?: string;
214	  error_description?: string;
215	};
216	
217	/**
218	 * Exchange an authorization code for an access token. Returns `{ error }`
219	 * (never throws) for a network failure or any error Discord's token endpoint
220	 * reports, so callers can show a friendly message instead of crashing.
221	 */
222	export async function discordExchangeCode(code: string, redirectUri: string = discordOauthRedirectUri()): Promise<{ accessToken?: string; error?: string }> {
223	  const clientId = await discordApplicationId();
224	  const clientSecret = await discordClientSecret();
225	  if (!clientId || !clientSecret) {
226	    return { error: "Discord sign-in isn't fully configured on this server yet." };
227	  }
228	
229	  const params = new URLSearchParams({
230	    client_id: clientId,
231	    client_secret: clientSecret,
232	    grant_type: "authorization_code",
233	    code,
234	    redirect_uri: redirectUri,
235	  });
236	
237	  let res: Response;
238	  try {
239	    res = await fetch(DISCORD_OAUTH_TOKEN_URL, {
240	      method: "POST",
241	      headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
242	      body: params.toString(),
243	      cache: "no-store",
244	    });
245	  } catch {
246	    return { error: "Couldn't reach Discord to finish connecting. Try again shortly." };
247	  }
248	
249	  let parsed: TokenResponse | null = null;
250	  try {
251	    parsed = (await res.json()) as TokenResponse;
252	  } catch {
253	    parsed = null;
254	  }
255	
256	  if (!res.ok || !parsed?.access_token) {
257	    const detail = parsed?.error_description || parsed?.error || `HTTP ${res.status}`;
258	    return { error: `Discord rejected the connection (${String(detail).slice(0, 160)}).` };
259	  }
260	
261	  return { accessToken: parsed.access_token };
262	}
263	
264	// ---------------------------------------------------------------------------
265	// Identify
266	// ---------------------------------------------------------------------------
267	
268	// `email`/`emailVerified` are only present when the `email` scope was
269	// requested AND granted — undefined otherwise (the `identify`-only linking
270	// flow never sees them, which is correct: that flow never asked for email).
271	export type DiscordSelfUser = { id: string; username: string; email?: string; emailVerified?: boolean };
272	
273	/** GET /users/@me with the just-obtained access token — the real Discord user id + username (+ email if that scope was granted). */
274	export async function fetchDiscordSelf(accessToken: string): Promise<{ user?: DiscordSelfUser; error?: string }> {
275	  let res: Response;
276	  try {
277	    res = await fetch(DISCORD_API_USERS_ME, {
278	      headers: { Authorization: `Bearer ${accessToken}` },
279	      cache: "no-store",
280	    });
281	  } catch {
282	    return { error: "Couldn't reach Discord to confirm your account. Try again shortly." };
283	  }
284	  if (!res.ok) {
285	    return { error: `Discord rejected the account lookup (HTTP ${res.status}).` };
286	  }
287	  let json: { id?: unknown; username?: unknown; email?: unknown; verified?: unknown } | null = null;
288	  try {
289	    json = await res.json();
290	  } catch {
291	    json = null;
292	  }
293	  if (!json || typeof json.id !== "string" || !json.id) {
294	    return { error: "Discord didn't return a usable account id." };
295	  }
296	  return {
297	    user: {
298	      id: json.id,
299	      username: typeof json.username === "string" ? json.username : "",
300	      email: typeof json.email === "string" && json.email ? json.email : undefined,
301	      emailVerified: typeof json.verified === "boolean" ? json.verified : undefined,
302	    },
303	  };
304	}
