78	/**
79	 * The subset of the PromoRedemption Prisma delegate this module uses, typed by
80	 * hand so the call sites stay type-checked even before the client is regenerated.
81	 */
82	type PromoWhere = {
83	  promoId?: string;
84	  userId?: string;
85	  ipHash?: string;
86	  orderRef?: string;
87	  renewed?: boolean;
88	  state?: string;
89	  reservationToken?: string;
90	  reservedUntil?: { lt: Date };
91	};
92	type PromoDelegate = {
93	  create(args: {
94	    data: {
95	      promoId?: string;
96	      userId: string;
97	      ipHash: string | null;
98	      serviceType: string;
99	      campaign: string;
100	      orderRef?: string | null;
101	      chargedCents: number;
102	      state?: string;
103	      reservedUntil?: Date | null;
104	      reservationToken?: string | null;
105	    };
106	    select?: { id: true };
107	  }): Promise<{ id: string }>;
108	  findUnique(args: {
109	    where: { promoId_userId: { promoId: string; userId: string } };
110	    select?: { id: true };
111	  }): Promise<{ id: string } | null>;
112	  findFirst(args: {
113	    where: PromoWhere;
114	    select?: { id: true };
115	  }): Promise<{ id: string } | null>;
116	  findMany(args?: {
117	    where?: PromoWhere;
118	    orderBy?: { createdAt: "asc" | "desc" };
119	  }): Promise<PromoRedemptionRow[]>;
120	  updateMany(args: {
121	    where: PromoWhere;
122	    data: { renewed?: boolean; renewedAt?: Date; state?: string; reservedUntil?: Date | null };
123	  }): Promise<{ count: number }>;
124	  update(args: {
125	    where: { id: string };
126	    data: { orderRef?: string | null; chargedCents?: number };
127	  }): Promise<{ id: string }>;
128	  deleteMany(args: { where: PromoWhere }): Promise<{ count: number }>;
129	  count(args?: { where?: PromoWhere }): Promise<number>;
130	};
