194	/**
195	 * Delete THIS claimant's own dead holds — RESERVED rows whose `reservedUntil` has
196	 * passed and which were never confirmed (an abandoned/expired card checkout). This
197	 * is the guarantee that an abandoned checkout can NEVER permanently burn a
198	 * customer's one eligibility: the very next claim/reserve attempt sweeps its own
199	 * stale hold before contending, independently of the webhook and the worker sweep.
200	 *
201	 * It is strictly guarded — `state: RESERVED` AND `reservedUntil < now` — so a
202	 * CONSUMED grant or a still-live hold is NEVER touched. Cleaning by ipHash frees
203	 * the shared-IP slot for anyone (a dead hold should block nobody), which is correct.
204	 */
205	async function releaseExpiredReservationsFor(
206	  d: PromoDelegate,
207	  userId: string,
208	  ipHash: string | null,
209	): Promise<void> {
210	  const now = new Date();
211	  await d.deleteMany({
212	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, state: PROMO_STATE.RESERVED, reservedUntil: { lt: now }, userId },
213	  });
214	  if (ipHash) {
215	    await d.deleteMany({
216	      where: { promoId: FIRST_MONTH_FREE_PROMO_ID, state: PROMO_STATE.RESERVED, reservedUntil: { lt: now }, ipHash },
217	    });
218	  }
219	}
220	
221	export type ClaimResult = { claimed: true; id: string } | { claimed: false };
222	
223	/**
224	 * THE ATOMIC CLAIM. Conditional INSERT of a PromoRedemption inside the caller's
225	 * charge transaction. Returns `{ claimed: true, id }` on success, or
226	 * `{ claimed: false }` when the row already exists for this account OR this IP
227	 * (Prisma P2002 on either unique constraint). Any OTHER database error is
228	 * rethrown so it rolls the whole charge tx back — a lost claim is expected and
229	 * cheap; an unexpected failure must not silently grant a free month.
230	 *
231	 * `orderRef` is usually still unknown here (the server/account id is generated
232	 * later in the same tx), so it is filled in afterwards via `setPromoOrderRef`.
233	 */
234	export async function claimFirstMonthFree(
235	  tx: Prisma.TransactionClient,
236	  opts: {
237	    userId: string;
238	    ipHash: string | null;
239	    serviceType: PromoServiceType;
240	    campaign: string;
241	    chargedCents: number;
242	    orderRef?: string | null;
243	  },
244	): Promise<ClaimResult> {
245	  try {
246	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout
247	    // must not stand between them and the free month on a fresh (wallet) order.
248	    await releaseExpiredReservationsFor(promoDelegate(tx), opts.userId, opts.ipHash);
249	    const row = await promoDelegate(tx).create({
250	      data: {
251	        promoId: FIRST_MONTH_FREE_PROMO_ID,
252	        userId: opts.userId,
253	        ipHash: opts.ipHash,
254	        serviceType: opts.serviceType,
255	        campaign: opts.campaign,
256	        orderRef: opts.orderRef ?? null,
257	        chargedCents: opts.chargedCents,
258	        // A direct grant. RESERVED is only ever produced by reserveFirstMonthFree.
259	        state: PROMO_STATE.CONSUMED,
260	      },
261	      select: { id: true },
262	    });
263	    return { claimed: true, id: row.id };
264	  } catch (e) {
265	    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
266	      // Unique violation on (promo,user) or (promo,ipHash): already redeemed.
267	      return { claimed: false };
268	    }
269	    throw e;
270	  }
271	}
