273	export type ReserveResult = { reserved: true; token: string } | { reserved: false };
274	
275	/**
276	 * THE CARD/STRIPE HOLD. Insert a RESERVED redemption BEFORE the card is charged, so
277	 * a second concurrent checkout can't also pass eligibility and walk away with a
278	 * second free month. This is the atomic gate for the up-front-settlement path — its
279	 * INSERT contends on the SAME two unique constraints as the grant, so exactly one of
280	 * N racing checkouts holds the slot; the losers get `{ reserved: false }` and the
281	 * caller re-quotes at FULL price (displayed === charged).
282	 *
283	 * Runs on the base client (not a tx): it is a single guarded insert, taken before
284	 * any Stripe session exists. The returned `token` is stamped into the Checkout
285	 * session's metadata and is what `confirmReservation` / `releaseReservation` target.
286	 */
287	export async function reserveFirstMonthFree(opts: {
288	  userId: string;
289	  ipHash: string | null;
290	  serviceType: PromoServiceType;
291	  campaign: string;
292	  chargedCents: number;
293	  /** When this hold may be reaped if never confirmed (session lifetime + grace). */
294	  reservedUntil: Date;
295	}): Promise<ReserveResult> {
296	  const d = promoDelegate(db);
297	  const token = `pmr_${randomUUID()}`;
298	  try {
299	    // Clear this claimant's own dead holds first, so an earlier abandoned checkout
300	    // never blocks a new one — the "no permanently-burned eligibility" guarantee.
301	    await releaseExpiredReservationsFor(d, opts.userId, opts.ipHash);
302	    await d.create({
303	      data: {
304	        promoId: FIRST_MONTH_FREE_PROMO_ID,
305	        userId: opts.userId,
306	        ipHash: opts.ipHash,
307	        serviceType: opts.serviceType,
308	        campaign: opts.campaign,
309	        chargedCents: opts.chargedCents,
310	        state: PROMO_STATE.RESERVED,
311	        reservedUntil: opts.reservedUntil,
312	        reservationToken: token,
313	      },
314	      select: { id: true },
315	    });
316	    return { reserved: true, token };
317	  } catch (e) {
318	    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
319	      // Unique violation on (promo,user) or (promo,ipHash): already held or redeemed.
320	      return { reserved: false };
321	    }
322	    throw e;
323	  }
324	}
325	
326	/**
327	 * Confirm a hold at fulfilment: flip its RESERVED row to CONSUMED, inside the order's
328	 * charge tx so the grant commits with the money. The `state: RESERVED` guard makes it
329	 * idempotent (a replayed fulfil, or a race with the sweep, matches zero rows) and
330	 * guarantees we never "confirm" a hold that was already released. Returns the row id
331	 * (to anchor `orderRef`), or null when there is no live hold to confirm.
332	 */
333	export async function confirmReservation(
334	  tx: Prisma.TransactionClient,
335	  token: string,
336	): Promise<{ id: string } | null> {
337	  const d = promoDelegate(tx);
338	  const row = await d.findFirst({
339	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, reservationToken: token },
340	    select: { id: true },
341	  });
342	  if (!row) return null;
343	  const res = await d.updateMany({
344	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, reservationToken: token, state: PROMO_STATE.RESERVED },
345	    data: { state: PROMO_STATE.CONSUMED, reservedUntil: null },
346	  });
347	  // count 0 => it was already consumed (a replay) or released; either way there is
348	  // nothing to newly grant on this call.
349	  return res.count === 1 ? { id: row.id } : null;
350	}
351	
352	/**
353	 * Release a hold (delete the RESERVED row) so an abandoned/expired checkout returns
354	 * the customer's one eligibility. Guarded to `state: RESERVED` so it can NEVER delete
355	 * a CONSUMED grant — a paid, confirmed free month is never revoked by a late expiry
356	 * event. Called from the `checkout.session.expired` webhook.
357	 */
358	export async function releaseReservation(token: string): Promise<void> {
359	  await promoDelegate(db).deleteMany({
360	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, reservationToken: token, state: PROMO_STATE.RESERVED },
361	  });
362	}
363	
364	/**
365	 * Backstop sweep: delete every RESERVED hold whose `reservedUntil` has passed. Runs
366	 * on the worker so a dead hold is reclaimed even if the `checkout.session.expired`
367	 * webhook is not configured or was missed. Returns how many were reaped. Guarded to
368	 * RESERVED, so a CONSUMED grant is untouchable here.
369	 */
370	export async function sweepExpiredReservations(now = new Date()): Promise<number> {
371	  const res = await promoDelegate(db).deleteMany({
372	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, state: PROMO_STATE.RESERVED, reservedUntil: { lt: now } },
373	  });
374	  return res.count;
375	}
376	
377	/**
378	 * Backfill the created server/account/subscription id (and the final charged
379	 * amount) onto a redemption we just claimed, in the same tx. Kept off the claim
380	 * itself because the resource id is minted after the claim within the tx.
381	 */
382	export async function setPromoOrderRef(
383	  tx: Prisma.TransactionClient,
384	  redemptionId: string,
385	  orderRef: string,
386	  chargedCents: number,
387	): Promise<void> {
388	  await promoDelegate(tx).update({
389	    where: { id: redemptionId },
390	    data: { orderRef, chargedCents },
391	  });
392	}
393	
394	/**
395	 * Mark the promo redemption anchored to `orderRef` as RENEWED, the first time
396	 * that service bills its SECOND term. Idempotent: the `renewed: false` guard
397	 * means a repeated/racing renewal sweep matches zero rows and does nothing.
398	 * Called inside the renewal charge tx so it commits with the money.
399	 */
400	export async function markPromoRenewed(
401	  tx: Prisma.TransactionClient,
402	  orderRef: string,
403	): Promise<void> {
404	  await promoDelegate(tx).updateMany({
405	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, orderRef, renewed: false },
406	    data: { renewed: true, renewedAt: new Date() },
407	  });
408	}
