442	// ---------------------------------------------------------------------------
443	// Admin stats
444	// ---------------------------------------------------------------------------
445	
446	export type PromoCampaignStat = {
447	  campaign: string;
448	  total: number;
449	  renewed: number;
450	};
451	
452	export type PromoStats = {
453	  total: number;
454	  renewed: number;
455	  /** renewed / total, 0..1. */
456	  conversion: number;
457	  byCampaign: PromoCampaignStat[];
458	  /** Approximate recovered revenue (one renewal term at list price), in cents. */
459	  revenueRecoveredCents: number;
460	  /** True when revenueRecovered had to fall back to an approximation. */
461	  revenueApproximate: boolean;
462	};
463	
464	/**
465	 * Aggregate redemption + conversion stats for the admin Promotions page.
466	 *
467	 * Revenue recovered is APPROXIMATE: for each renewed redemption we price ONE
468	 * renewal term at the underlying plan's current list price (VPS/hosting use the
469	 * plan monthly price; email/game use their stored term price). It is a lower/near
470	 * estimate — it ignores add-ons and multi-term VPS — hence `revenueApproximate`.
471	 */
472	export async function promoStats(): Promise<PromoStats> {
473	  // CONSUMED only — a RESERVED hold is a pending card checkout, not a granted
474	  // redemption, and counting it would inflate the total until it settled or expired.
475	  const rows = await promoDelegate(db).findMany({
476	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, state: PROMO_STATE.CONSUMED },
477	    orderBy: { createdAt: "desc" },
478	  });
479	
480	  const total = rows.length;
481	  const renewedRows = rows.filter((r) => r.renewed);
482	  const renewed = renewedRows.length;
483	
484	  const byCampaignMap = new Map<string, PromoCampaignStat>();
485	  for (const r of rows) {
486	    const key = r.campaign || "(organic)";
487	    const stat = byCampaignMap.get(key) ?? { campaign: key, total: 0, renewed: 0 };
488	    stat.total += 1;
489	    if (r.renewed) stat.renewed += 1;
490	    byCampaignMap.set(key, stat);
491	  }
492	  const byCampaign = [...byCampaignMap.values()].sort((a, b) => b.total - a.total);
493	
494	  // Approximate recovered revenue: one renewal term at list price per renewed row.
495	  let revenueRecoveredCents = 0;
496	  let revenueApproximate = false;
497	  const refs = (type: PromoServiceType) =>
498	    renewedRows.filter((r) => r.serviceType === type && r.orderRef).map((r) => r.orderRef as string);
499	
500	  const vpsRefs = refs("VPS");
501	  const gameRefs = refs("GAME");
502	  const serverRefs = [...vpsRefs, ...gameRefs];
503	  if (serverRefs.length) {
504	    const servers = await db.server.findMany({
505	      where: { id: { in: serverRefs } },
506	      select: { id: true, plan: { select: { priceCents: true } }, gamePlan: { select: { priceCents: true } } },
507	    });
508	    for (const s of servers) {
509	      revenueRecoveredCents += s.gamePlan?.priceCents ?? s.plan?.priceCents ?? 0;
510	    }
511	    revenueApproximate = true;
512	  }
513	
514	  const hostRefs = refs("HOSTING");
515	  if (hostRefs.length) {
516	    const accounts = await db.hostingAccount.findMany({
517	      where: { id: { in: hostRefs } },
518	      select: { plan: { select: { priceCents: true } } },
519	    });
520	    for (const a of accounts) revenueRecoveredCents += a.plan?.priceCents ?? 0;
521	    revenueApproximate = true;
522	  }
523	
524	  const emailRefs = refs("EMAIL");
525	  if (emailRefs.length) {
526	    const subs = await db.emailSubscription.findMany({
527	      where: { id: { in: emailRefs } },
528	      select: { emailPlan: { select: { priceCents: true } } },
529	    });
530	    for (const s of subs) revenueRecoveredCents += s.emailPlan?.priceCents ?? 0;
531	    revenueApproximate = true;
532	  }
533	
534	  return {
535	    total,
536	    renewed,
537	    conversion: total > 0 ? renewed / total : 0,
538	    byCampaign,
539	    revenueRecoveredCents,
540	    revenueApproximate,
541	  };
542	}
