31	export type DiscordLinkStatus = {
32	  connected: boolean;
33	  /** Best-effort display username — null if unlinked or the lookup failed/was skipped. */
34	  username: string | null;
35	  /** Is "Connect Discord" available in this environment (app id + client secret configured)? */
36	  oauthAvailable: boolean;
