41	/** Connection state for the current staff member. Never returns anything sensitive. */
42	export async function getDiscordLinkStatus(): Promise<DiscordLinkStatus> {
43	  const me = await requireArea("support");
44	  const discordUserId = (me as unknown as { discordUserId?: string | null }).discordUserId ?? null;
45	
46	  let username: string | null = null;
47	  if (discordUserId) {
